/* ============================================================
   Web platform — LaDe routes (English version)
   Every displayed value comes from data_en/donnees.js,
   generated by the Notebook (source of truth).
   French version: index.html + app.js
   ============================================================ */
(function () {
  "use strict";
  const P = window.PROJET;
  if (!P) { document.getElementById("erreur-donnees").hidden = false; return; }

  // ---------- Helpers ----------
  const $ = (s, r = document) => r.querySelector(s);
  const fmt = (x, d = 1) => Number(x).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
  const fmtInt = (x) => Math.round(x).toLocaleString("en-US");
  const pct = (x, d = 0) => fmt(100 * x, d) + "%";
  const signed = (x, d = 1) => (x > 0 ? "+" : x < 0 ? "−" : "") + fmt(Math.abs(x), d) + "%";
  const change = (a, b) => (100 * (b - a)) / a;
  const clock = (min) => { const m = Math.round(min); const h = Math.floor(m / 60); return String(h).padStart(2, "0") + ":" + String(((m % 60) + 60) % 60).padStart(2, "0"); };
  const C = { reel: "#8a8985", sans: "#eb6834", avec: "#2a78d6", gris: "#52606d", trait: "#e9eef4" };
  const NAMES = { reel: "Real (courier)", sans_ml: "Optimised without ML", avec_ml: "Optimised with ML" };
  const COLOR = { reel: C.reel, sans_ml: C.sans, avec_ml: C.avec };
  const ind = P.eda.indicateurs, op = P.optim, ml = P.ml;
  const K = Object.fromEntries(op.kpi_moyens.map((r) => [r.strategie, r]));
  const KR = K[NAMES.reel], KS = K[NAMES.sans_ml], KM = K[NAMES.avec_ml];
  const MOD = Object.fromEntries(ml.modeles.map((m) => [m.modele, m]));
  const BASE = MOD["Baseline (historical averages)"], FIN = MOD[ml.modele_final];
  const SC = P.scenarios;
  const SIM = window.Simulateur.creer(SC.heure_min, SC.heure_max);
  const charts = {};

  if (window.Chart) {
    Chart.defaults.font.family = '"Public Sans", system-ui, sans-serif';
    Chart.defaults.font.size = 12;
    Chart.defaults.color = "#52606d";
    Chart.defaults.borderColor = C.trait;
    Chart.defaults.plugins.legend.labels.boxWidth = 12;
    Chart.defaults.plugins.legend.labels.boxHeight = 12;
    Chart.defaults.maintainAspectRatio = false;
    Chart.defaults.animation.duration = 400;
  }
  function chart(id, config) {
    const el = document.getElementById(id);
    if (!el || !window.Chart) return null;
    if (charts[id]) charts[id].destroy();
    charts[id] = new Chart(el, config);
    return charts[id];
  }
  const axis = (title, extra = {}) => ({ title: { display: !!title, text: title }, grid: { color: C.trait }, ...extra });

  // ---------- Map (canvas, no base map: works offline) ----------
  function drawMap(canvas, sc, routes, opts = {}) {
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth, h = canvas.clientHeight;
    canvas.width = w * dpr; canvas.height = h * dpr;
    const ctx = canvas.getContext("2d"); ctx.scale(dpr, dpr); ctx.clearRect(0, 0, w, h);
    const lat0 = sc.lat[0], kx = 111.32 * Math.cos((lat0 * Math.PI) / 180), ky = 110.57;
    const X = sc.lng.map((v) => (v - sc.lng[0]) * kx), Y = sc.lat.map((v) => (v - sc.lat[0]) * ky);
    const minX = Math.min(...X), maxX = Math.max(...X), minY = Math.min(...Y), maxY = Math.max(...Y);
    const pad = 34, sx = (w - 2 * pad) / Math.max(maxX - minX, 0.05), sy = (h - 2 * pad) / Math.max(maxY - minY, 0.05);
    const s = Math.min(sx, sy);
    const ox = (w - (maxX - minX) * s) / 2, oy = (h - (maxY - minY) * s) / 2;
    const px = (i) => ox + (X[i] - minX) * s, py = (i) => h - (oy + (Y[i] - minY) * s);
    // scale bar
    const km = [0.1, 0.2, 0.5, 1, 2, 5, 10].find((k) => k * s > 60) || 10;
    ctx.strokeStyle = "#7b8794"; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(14, h - 14); ctx.lineTo(14 + km * s, h - 14); ctx.stroke();
    ctx.fillStyle = "#52606d"; ctx.font = "12px Public Sans, sans-serif"; ctx.fillText(fmt(km, km < 1 ? 1 : 0) + " km", 18 + km * s, h - 10);
    routes.forEach((r) => {
      ctx.strokeStyle = r.couleur; ctx.lineWidth = r.epaisseur || 2.4; ctx.globalAlpha = r.alpha ?? 1;
      ctx.setLineDash(r.pointille ? [6, 5] : []); ctx.lineJoin = "round";
      ctx.beginPath(); r.ordre.forEach((j, k) => (k ? ctx.lineTo(px(j), py(j)) : ctx.moveTo(px(j), py(j)))); ctx.stroke();
    });
    ctx.setLineDash([]); ctx.globalAlpha = 1;
    const ref = routes[routes.length - 1];
    const rank = new Array(sc.n); ref.ordre.forEach((j, k) => (rank[j] = k + 1));
    for (let i = 0; i < sc.n; i++) {
      const late = opts.retards && opts.retards.has(i);
      ctx.beginPath(); ctx.arc(px(i), py(i), 10, 0, 2 * Math.PI);
      ctx.fillStyle = "#fff"; ctx.fill(); ctx.lineWidth = 2; ctx.strokeStyle = late ? "#b5410f" : ref.couleur; ctx.stroke();
      ctx.fillStyle = "#102a43"; ctx.font = "600 11px Public Sans, sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(String(rank[i]), px(i), py(i) + 0.5);
    }
    ctx.textAlign = "start"; ctx.textBaseline = "alphabetic";
  }

  // ---------- Navigation ----------
  const rendered = {};
  const PAGES = { home: renderHome, data: renderData, preparation: renderPreparation, eda: renderEDA,
                  ml: renderML, simulator: renderSimulator, comparison: renderComparison, conclusion: renderConclusion };
  function show(name) {
    if (!PAGES[name]) name = "home";
    document.querySelectorAll(".page").forEach((p) => p.classList.toggle("active", p.id === "page-" + name));
    document.querySelectorAll("nav a").forEach((a) => { if (a.dataset.page === name) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current"); });
    if (!rendered[name]) { PAGES[name]($("#page-" + name)); rendered[name] = true; }
    $("#nav").classList.remove("ouvert"); $(".menu-mobile").setAttribute("aria-expanded", "false");
    window.scrollTo(0, 0);
  }
  window.addEventListener("hashchange", () => show(location.hash.slice(1)));
  $(".menu-mobile").addEventListener("click", (e) => { const o = $("#nav").classList.toggle("ouvert"); e.currentTarget.setAttribute("aria-expanded", String(o)); });

  // Demo scenario: the Notebook's example day if exported, otherwise the median-gain day
  function demoScenario() {
    const ex = SC.scenarios.find((s) => s.id === op.exemple.journee);
    if (ex) return ex;
    const sorted = SC.scenarios.slice().sort((a, b) => (a.resultats_notebook.reel.distance_km - a.resultats_notebook.avec_ml.distance_km) - (b.resultats_notebook.reel.distance_km - b.resultats_notebook.avec_ml.distance_km));
    return sorted[Math.floor(sorted.length / 2)];
  }
  const dayName = (sc) => "Courier " + sc.courier_id + ", " + String(sc.ds).padStart(4, "0").slice(0, 2) + "/" + String(sc.ds).padStart(4, "0").slice(2) + ", " + sc.n + " visits";

  // ======================= 1. HOME =======================
  function renderHome(el) {
    const demo = demoScenario();
    const rReal = SIM.simuler(demo, "reel", SC.lambda_defaut), rMl = SIM.simuler(demo, "avec_ml", SC.lambda_defaut);
    el.innerHTML = `
      <div class="hero">
        <div class="hero-texte">
          <h1 id="t-home">After every pickup, the courier has to choose where to go next. We help them choose better.</h1>
          <p class="chapeau">In Yantai, each parcel must be collected before the end of a 2-hour window, and requests arrive throughout the day.
          A Machine Learning model <b>predicts the time</b> between two pickup points; an optimisation algorithm <b>decides the visiting order</b> at every stop.</p>
          <div class="chiffres" style="grid-template-columns:repeat(2,minmax(0,1fr))">
            <div class="chiffre bon"><div class="val">${signed(op.gains.distance_avec_vs_reel_pct)}</div><div class="lib">distance compared with real couriers (average over ${op.n_journees} test days)</div></div>
            <div class="chiffre bon"><div class="val">${signed(op.gains.deplacement_avec_vs_reel_pct)}</div><div class="lib">travel time, in simulation</div></div>
            <div class="chiffre ml"><div class="val">${signed(change(KS.n_retard, KM.n_retard), 0)}</div><div class="lib">late pickups thanks to ML, compared with optimisation without ML</div></div>
            <div class="chiffre"><div class="val">${pct(op.milp_vs_heuristique.part_optimum)}</div><div class="lib">of test instances solved to proven optimality by our heuristic (HiGHS MILP)</div></div>
          </div>
        </div>
        <figure class="hero-carte" style="margin:0">
          <canvas id="carte-hero" aria-label="Map of the two routes of the demo day"></canvas>
          <figcaption class="legende-carte">
            <span><i style="background:${C.reel}"></i>Real order: ${fmt(rReal.distance_km, 1)} km</span>
            <span><i style="background:${C.avec}"></i>Optimised with ML: ${fmt(rMl.distance_km, 1)} km</span>
            <span>${dayName(demo)}, a test day with the median gain; numbers = optimised order, recomputed in your browser</span>
          </figcaption>
        </figure>
      </div>
      <div class="chaine" aria-label="Project approach">
        <div><b>Data</b>${fmtInt(ind.colis)} real parcels from ${fmtInt(ind.coursiers)} couriers (LaDe, Cainiao)</div>
        <div class="ml"><b>ML model</b>Gradient Boosting: time between two visits from distance, place, hour</div>
        <div class="ml"><b>Predictions</b>One time matrix per hour, for each day</div>
        <div class="opt"><b>Decision</b>At each stop, optimise the order of the known visits (TSPTW)</div>
        <div class="opt"><b>Evaluation</b>Real, without ML and with ML scored by an independent evaluator</div>
      </div>
      <div class="grille g2 bloc">
        <div class="panneau">
          <h3>The business problem</h3>
          <p>A bad visiting order adds kilometres, uses up working time and misses deadlines.
          Since only ${pct(ind.part_connue_avant_debut)} of the tasks are known before the first pickup, the order cannot be fixed in the morning: it has to be <b>recomputed at every stop</b>.</p>
          <h3 style="margin-top:14px">The objectives</h3>
          <ul class="liste-simple"><li>Predict the time between two visits better than a historical average.</li><li>Use these predictions in an optimisation model.</li><li>Measure the gain in distance, time and lateness honestly.</li></ul>
        </div>
        <div class="panneau">
          <h3>Average KPIs per test day</h3>
          <p class="sous">${op.n_journees} days from September–October, λ = ${fmt(op.lambda, 0)}</p>
          <div class="grille g2" style="gap:10px"><div class="graph bas"><canvas id="g-acc-km"></canvas></div><div class="graph bas"><canvas id="g-acc-ret"></canvas></div></div>
          <p class="lecture">Optimisation shortens routes; without ML, it causes more lateness than the field. With ML, it keeps the gain and reduces lateness.</p>
        </div>
      </div>`;
    const mapRoutes = () => [
      { ordre: rReal.ordre, couleur: C.reel, epaisseur: 2, alpha: 0.75, pointille: true },
      { ordre: rMl.ordre, couleur: C.avec, epaisseur: 2.6 }];
    requestAnimationFrame(() => drawMap($("#carte-hero"), demo, mapRoutes()));
    window.addEventListener("resize", () => { if ($("#page-home").classList.contains("active")) drawMap($("#carte-hero"), demo, mapRoutes()); });
    const miniK = (id, title, field, unit, d) => chart(id, { type: "bar", data: { labels: ["Real", "No ML", "With ML"],
      datasets: [{ label: title, data: ["reel", "sans_ml", "avec_ml"].map((s) => K[NAMES[s]][field]), backgroundColor: [C.reel, C.sans, C.avec], borderRadius: 4 }] },
      options: { plugins: { legend: { display: false }, title: { display: true, text: title }, tooltip: { callbacks: { label: (c) => fmt(c.raw, d) + " " + unit } } },
        scales: { y: axis("", { beginAtZero: true }), x: { grid: { display: false } } } } });
    miniK("g-acc-km", "Distance (km / day)", "distance_km", "km", 2);
    miniK("g-acc-ret", "Late pickups / day", "n_retard", "late", 2);
  }

  // ======================= 2. DATA =======================
  function renderData(el) {
    const cols = P.echantillon.colonnes, rows = P.echantillon.lignes;
    const shownCols = ["order_id", "courier_id", "ds", "region_id", "aoi_type", "lng", "lat", "accept_time", "time_window_start", "time_window_end", "pickup_time"];
    const idx = shownCols.map((c) => cols.indexOf(c));
    const types = [...new Set(rows.map((l) => l[cols.indexOf("aoi_type")]))].sort((a, b) => a - b);
    const regions = [...new Set(rows.map((l) => l[cols.indexOf("region_id")]))].sort((a, b) => a - b);
    el.innerHTML = `
      <div class="entete"><h2 id="t-data">Explore the data</h2>
        <p>Public dataset <b>LaDe-P</b> (Cainiao, Apache-2.0 licence), city of Yantai. Each row is a parcel to collect. The table shows a random sample of ${fmtInt(rows.length)} parcels; the Notebook works on all ${fmtInt(ind.colis)}.</p></div>
      <div class="chiffres">
        <div class="chiffre"><div class="val">${fmtInt(ind.colis)}</div><div class="lib">rows (parcels)</div></div>
        <div class="chiffre"><div class="val">${ind.colonnes}</div><div class="lib">columns</div></div>
        <div class="chiffre"><div class="val">${fmtInt(ind.coursiers)}</div><div class="lib">couriers, ${ind.regions} regions</div></div>
        <div class="chiffre"><div class="val">${ind.jours}<small> days</small></div><div class="lib">from May to October</div></div>
      </div>
      <div class="panneau bloc">
        <div class="outils">
          <label class="champ">Search (identifier, courier, date…)<input type="search" id="f-texte" placeholder="e.g. 992 or 05-18"></label>
          <label class="champ">AOI type<select id="f-type"><option value="">All</option>${types.map((t) => `<option>${t}</option>`).join("")}</select></label>
          <label class="champ">Region<select id="f-region"><option value="">All</option>${regions.map((t) => `<option>${t}</option>`).join("")}</select></label>
        </div>
        <div class="table-zone"><table><thead><tr>${shownCols.map((c) => `<th>${c}</th>`).join("")}</tr></thead><tbody id="t-corps"></tbody></table></div>
        <div class="pagination"><button id="p-prec">Previous page</button><span id="p-info"></span><button id="p-suiv">Next page</button></div>
      </div>
      <div class="panneau bloc"><h3>What are the variables for?</h3>
        <div class="table-zone"><table><thead><tr><th>Variable</th><th>Meaning</th><th>Role in the project</th></tr></thead><tbody>
          <tr><td>courier_id, ds</td><td>courier and date (MMDD)</td><td>group parcels into route days</td></tr>
          <tr><td>lng, lat</td><td>coordinates of the pickup point</td><td>distances between visits</td></tr>
          <tr><td>region_id, aoi_id, aoi_type</td><td>zone, area of interest and its type</td><td>ML explanatory variables</td></tr>
          <tr><td>time_window_end</td><td>end of the promised window</td><td>deadline in the optimisation</td></tr>
          <tr><td>accept_time</td><td>moment the task becomes known</td><td>a task is never planned before it exists</td></tr>
          <tr><td>pickup_time</td><td>actual pickup moment</td><td>real courier order and ML target</td></tr>
          <tr><td>*_gps_*</td><td>courier's GPS position</td><td>not used (21% to 36% missing)</td></tr>
        </tbody></table></div></div>`;
    let page = 0; const perPage = 15;
    const filter = () => {
      const q = $("#f-texte").value.trim().toLowerCase(), ty = $("#f-type").value, rg = $("#f-region").value;
      return rows.filter((l) => (!ty || String(l[cols.indexOf("aoi_type")]) === ty) && (!rg || String(l[cols.indexOf("region_id")]) === rg)
        && (!q || idx.some((i) => String(l[i]).toLowerCase().includes(q))));
    };
    const update = () => {
      const f = filter(); const nb = Math.max(1, Math.ceil(f.length / perPage)); page = Math.min(page, nb - 1);
      $("#t-corps").innerHTML = f.slice(page * perPage, (page + 1) * perPage).map((l) => "<tr>" + idx.map((i) => `<td class="${typeof l[i] === "number" ? "num" : ""}">${l[i] ?? ""}</td>`).join("") + "</tr>").join("")
        || `<tr><td colspan="${idx.length}">No parcel matches these filters. Clear the search or choose “All”.</td></tr>`;
      $("#p-info").textContent = `${fmtInt(f.length)} parcels, page ${page + 1} of ${nb}`;
      $("#p-prec").disabled = page === 0; $("#p-suiv").disabled = page >= nb - 1;
    };
    ["#f-texte", "#f-type", "#f-region"].forEach((s) => $(s).addEventListener("input", () => { page = 0; update(); }));
    $("#p-prec").addEventListener("click", () => { page--; update(); });
    $("#p-suiv").addEventListener("click", () => { page++; update(); });
    update();
  }

  // ======================= 3. PREPARATION =======================
  function renderPreparation(el) {
    const J = P.eda.journal_preprocessing;
    const explain = {
      "Raw data": "The pickup_yt.csv file is loaded as is.",
      "Exact duplicates": "No row is repeated: nothing to remove.",
      "Duplicate identifiers": "Each parcel has a unique identifier.",
      "Pickup before acceptance": "No parcel is collected before the task is known: dates are consistent.",
      "Reversed window": "No window ends before it starts.",
      "Points outside the Yantai area": "All coordinates are plausible: nothing removed.",
      "Visits built": "Several consecutive parcels at the same place form a single visit: the courier does not move between them.",
      "Consecutive pairs": "Each move from one visit to the next becomes a training example.",
      "Causal pairs": "We keep the trip only if the next visit was already known at departure; otherwise the gap measures a wait, not a trip.",
      "Breaks excluded from training": "Beyond 120 min, it is no longer a trip but a break: excluded from training, kept in the real routes.",
      "Training pairs": "Final base: 9 variables known before leaving, without data leakage.",
    };
    const missing = Object.entries(P.eda.valeurs_manquantes);
    el.innerHTML = `
      <div class="entete"><h2 id="t-preparation">Data preparation</h2>
        <p>From the raw file to the training base. Each step is justified; no row is removed without a reason.</p></div>
      <div class="grille g2">
        <div class="panneau"><h3>Initial state: missing values per column</h3>
          <p class="sous">Only the GPS columns have gaps; they are not used by the model.</p>
          <div class="graph haut"><canvas id="g-manq"></canvas></div></div>
        <div class="panneau"><h3>From parcel to training trip</h3>
          <p class="sous">Number of rows at each key step</p>
          <div class="graph haut"><canvas id="g-entonnoir"></canvas></div></div>
      </div>
      <div class="panneau bloc"><h3>The steps, in order</h3>
        <ol class="etapes">${J.map((r) => `<li><div><b>${r.etape}</b><p>${explain[r.etape] || r.explication}</p></div><span class="nb">${fmtInt(r.lignes)}</span></li>`).join("")}</ol></div>
      <div class="grille g2 bloc">
        <div class="encadre"><h3>Split without data leakage</h3><p>The model learns on <b>May to August</b> and is tested on <b>September–October</b>: we never predict the past with the future. Couriers are randomly drawn into two disjoint groups. Group A trains the model that <b>decides</b>; group B trains a model that <b>scores</b> the routes. The model that decides is never the one that scores.</p></div>
        <div class="encadre orange"><h3>What we cannot know</h3><p>The year is not in the dates: the day of the week is unknown and is therefore not used. The actual pickup times of the target visit are never explanatory variables.</p></div>
      </div>`;
    chart("g-manq", { type: "bar", data: { labels: missing.map((m) => m[0]), datasets: [{ label: "Missing values (%)", data: missing.map((m) => (100 * m[1]) / ind.colis), backgroundColor: missing.map((m) => (m[1] ? C.sans : C.avec)), borderRadius: 3 }] },
      options: { indexAxis: "y", plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => fmt(c.raw, 1) + "% missing" } } }, scales: { x: axis("% of rows missing", { max: 40 }), y: { grid: { display: false }, ticks: { font: { size: 11 } } } } } });
    const steps = ["Raw data", "Visits built", "Consecutive pairs", "Causal pairs", "Training pairs"];
    const Jm = Object.fromEntries(J.map((r) => [r.etape, r.lignes]));
    chart("g-entonnoir", { type: "bar", data: { labels: ["Parcels", "Visits", "Consecutive pairs", "Causal pairs", "Training base"], datasets: [{ label: "Rows", data: steps.map((e) => Jm[e]), backgroundColor: C.avec, borderRadius: 4 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => fmtInt(c.raw) + " rows" } } }, scales: { y: axis("Rows", { beginAtZero: true }), x: { grid: { display: false } } } } });
  }

  // ======================= 4. EDA =======================
  function renderEDA(el) {
    const E = P.eda;
    const card = (id, title, sub, reading, cls = "") => `<div class="panneau"><h3>${title}</h3><p class="sous">${sub}</p><div class="graph ${cls}"><canvas id="${id}"></canvas></div><p class="lecture">${reading}</p></div>`;
    el.innerHTML = `
      <div class="entete"><h2 id="t-eda">Exploratory analysis</h2><p>Each chart answers a logistics question that guides the model or the optimisation. Hover over the charts to read the values.</p></div>
      <div class="grille g2">
        ${card("g-vol", "Is the volume stable?", "Parcels collected per day", "Activity peaks in June then stabilises around 6,000 parcels/day. The test period (Sept.–Oct.) remains comparable to training.")}
        ${card("g-ecarts", "How long between two visits?", "Distribution of gaps (min, capped at 200)", `Median of <b>${fmt(ind.ecart_median, 0)} min</b>, but a long tail: beyond 120 min these are breaks, excluded from training.`)}
        ${card("g-dist", "Does distance explain time?", "Median time and central 50% by distance range", "Time is <b>not proportional</b> to distance: it plateaus around 13 min then decreases for long trips. For the same distance, the dispersion is large.")}
        <div class="panneau"><h3>Does the time of day matter?</h3><p class="sous">Time between visits by departure hour</p>
          <div class="bascule" role="group" aria-label="Statistic displayed"><button aria-pressed="true" data-stat="moyenne">Mean</button><button aria-pressed="false" data-stat="mediane">Median</button></div>
          <div class="graph" style="margin-top:8px"><canvas id="g-heure"></canvas></div>
          <p class="lecture">The morning is fast; in the afternoon, the average time rises to about 20 min. The time matrix must therefore <b>depend on the hour</b>.</p></div>
        ${card("g-marge", "Are time windows respected?", "Minutes left before the deadline at pickup time", `Only <b>${pct(ind.taux_retard_reel, 2)}</b> real lateness, and ${pct(ind.taux_avant_fenetre)} of parcels collected before the window start. The expected gain concerns time and distance.`)}
        ${card("g-type", "Does the type of place influence time?", "Mean time by arrival AOI type (8 most frequent types)", "Modest differences (14 to 16 min): useful but secondary information, which the variable importance confirms.")}
        ${card("g-taille", "How big is a route?", "Visits per courier day (capped at 60)", "Days with 10 to 30 visits are where the order really matters: these are the ones we optimise.")}
        <div class="panneau"><h3>Where are the pickup points?</h3><p class="sous">4,000 randomly drawn visits; colour = region</p>
          <div class="graph"><canvas id="g-points"></canvas></div>
          <p class="lecture">Several separate urban hubs: routes stay local, and the region provides useful information to the model.</p></div>
      </div>
      <div class="panneau bloc"><h3>Correlations between variables (Spearman)</h3><p class="sous">The darker the cell, the stronger the link</p>
        <div class="table-zone"><table class="corr" id="t-corr"></table></div>
        <p class="lecture">Distance (0.27) and hour (0.17) are the variables most related to time, but all correlations remain weak: a <b>non-linear</b> model combining the variables is needed.</p></div>`;
    chart("g-vol", { type: "line", data: { labels: E.volume_quotidien.dates, datasets: [{ label: "Parcels per day", data: E.volume_quotidien.colis, borderColor: C.avec, borderWidth: 2, pointRadius: 0, tension: 0.2 }] },
      options: { interaction: { mode: "index", intersect: false }, plugins: { legend: { display: false } }, scales: { y: axis("Parcels per day"), x: { ticks: { maxTicksLimit: 8 }, grid: { display: false } } } } });
    const centers = (b) => b.slice(0, -1).map((x, i) => (x + b[i + 1]) / 2);
    chart("g-ecarts", { type: "bar", data: { labels: centers(E.hist_ecarts.bords).map((x) => fmt(x, 0)), datasets: [{ label: "Trips", data: E.hist_ecarts.valeurs, backgroundColor: E.hist_ecarts.bords.slice(0, -1).map((x) => (x >= 120 ? C.sans : C.avec)), barPercentage: 1, categoryPercentage: 0.95 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { title: (c) => "Around " + c[0].label + " min", label: (c) => fmtInt(c.raw) + " trips" } } }, scales: { y: axis("Trips"), x: axis("Gap (min)", { grid: { display: false }, ticks: { maxTicksLimit: 11 } }) } } });
    const D = E.temps_vs_distance;
    chart("g-dist", { type: "line", data: { labels: D.bandes, datasets: [
      { label: "3rd quartile", data: D.q75, borderColor: "rgba(42,120,214,.25)", backgroundColor: "rgba(42,120,214,.15)", fill: "+1", pointRadius: 0 },
      { label: "1st quartile", data: D.q25, borderColor: "rgba(42,120,214,.25)", pointRadius: 0, fill: false },
      { label: "Median", data: D.mediane, borderColor: C.avec, borderWidth: 2.2, pointRadius: 3, pointBackgroundColor: C.avec }] },
      options: { interaction: { mode: "index", intersect: false }, plugins: { legend: { labels: { filter: (l) => l.text !== "1st quartile" } } }, scales: { y: axis("Time (min)"), x: { grid: { display: false } } } } });
    const H = E.par_heure;
    const gH = chart("g-heure", { type: "bar", data: { labels: H.heures.map((h) => h + ":00"), datasets: [{ label: "Mean time (min)", data: H.moyenne, backgroundColor: C.avec, borderRadius: 3 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { afterLabel: (c) => fmtInt(H.n[c.dataIndex]) + " trips" } } }, scales: { y: axis("Time (min)", { beginAtZero: true }), x: { grid: { display: false } } } } });
    el.querySelectorAll(".bascule button").forEach((b) => b.addEventListener("click", () => {
      el.querySelectorAll(".bascule button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
      if (gH) { const st = b.dataset.stat; gH.data.datasets[0].data = H[st]; gH.data.datasets[0].label = st === "moyenne" ? "Mean time (min)" : "Median time (min)"; gH.update(); }
    }));
    const M = E.hist_marge;
    chart("g-marge", { type: "bar", data: { labels: centers(M.bords).map((x) => fmt(x, 0)), datasets: [{ label: "Parcels", data: M.valeurs, backgroundColor: M.bords.slice(0, -1).map((x) => (x < 0 ? C.sans : C.avec)), barPercentage: 1, categoryPercentage: 0.95 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { title: (c) => c[0].label + " min before the deadline", label: (c) => fmtInt(c.raw) + " parcels" } } }, scales: { y: axis("Parcels"), x: axis("Minutes before the deadline (negative = late)", { grid: { display: false }, ticks: { maxTicksLimit: 12 } }) } } });
    const T = E.par_type_aoi;
    chart("g-type", { type: "bar", data: { labels: T.types.map((t) => "type " + t), datasets: [{ label: "Mean time (min)", data: T.moyenne, backgroundColor: C.avec, borderRadius: 3 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { afterLabel: (c) => fmtInt(T.n[c.dataIndex]) + " trips" } } }, scales: { y: axis("Mean time (min)", { beginAtZero: true }), x: { grid: { display: false } } } } });
    const S = E.hist_taille;
    chart("g-taille", { type: "bar", data: { labels: S.bords.slice(0, -1).map((x) => fmt(x, 0)), datasets: [{ label: "Days", data: S.valeurs, backgroundColor: S.bords.slice(0, -1).map((x) => (x >= 10 && x <= 30 ? C.sans : C.avec)), barPercentage: 1, categoryPercentage: 0.95 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { title: (c) => c[0].label + " visits", label: (c) => fmtInt(c.raw) + " days" } } }, scales: { y: axis("Courier days"), x: axis("Visits in the day", { grid: { display: false }, ticks: { maxTicksLimit: 12 } }) } } });
    const pts = E.points_carte, regs = [...new Set(pts.map((p) => p[2]))].sort((a, b) => a - b);
    const hue = (r) => `hsl(${(regs.indexOf(r) * 137.5) % 360} 55% 45%)`;
    chart("g-points", { type: "scatter", data: { datasets: [{ label: "Visits", data: pts.map((p) => ({ x: p[0], y: p[1], r: p[2] })), pointRadius: 1.4, pointBackgroundColor: pts.map((p) => hue(p[2])), pointBorderWidth: 0 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => "Region " + c.raw.r + " (" + fmt(c.raw.x, 3) + "; " + fmt(c.raw.y, 3) + ")" } } }, scales: { x: axis("Longitude"), y: axis("Latitude") } } });
    const V = E.correlations.variables, MAT = E.correlations.matrice;
    $("#t-corr").innerHTML = "<thead><tr><th></th>" + V.map((v) => `<th>${v}</th>`).join("") + "</tr></thead><tbody>" +
      V.map((v, i) => `<tr><th>${v}</th>` + MAT[i].map((x) => { const a = Math.abs(x); const c = x >= 0 ? `rgba(42,120,214,${a * 0.85})` : `rgba(235,104,52,${a * 0.85})`; return `<td style="background:${c};color:${a > 0.55 ? "#fff" : "#1f2933"}">${fmt(x, 2)}</td>`; }).join("") + "</tr>").join("") + "</tbody>";
  }

  // ======================= 5. ML =======================
  function renderML(el) {
    const names = ml.modeles.map((m) => m.modele);
    const modelColors = names.map((n) => (n === ml.modele_final ? C.avec : n.startsWith("Baseline") ? C.sans : C.reel));
    el.innerHTML = `
      <div class="entete"><h2 id="t-ml">Machine Learning models</h2>
        <p>The model predicts the <b>time in minutes between the end of one visit and the start of the next</b>. It learns from ${fmtInt(ml.tailles.train)} trips (May–Aug.) and is tested on ${fmtInt(ml.tailles.test)} unseen trips (Sept.–Oct.).</p></div>
      <div class="grille g2">
        <div class="encadre"><h3>How the model turns data into a prediction</h3>
          <p>For each pair of points, it is given 9 pieces of information known <b>before</b> leaving: distance, same area of interest or not, place types, hour, number of parcels, region and arrival coordinates.</p>
          <p>Gradient Boosting builds hundreds of small "if… then…" decision trees. Each tree corrects the errors of the previous ones, and the prediction is the sum of their answers. For one day, we query the model on <b>all pairs of points, for every hour</b>: this gives the time matrix the optimiser uses.</p></div>
        <div class="panneau"><h3>The models compared</h3>
          <ul class="liste-simple">
            <li><b>Baseline</b> (no ML): ${fmt(ml.baseline.service_median_min, 0)} min of service + distance ÷ ${fmt(ml.baseline.vitesse_mediane_kmh, 1)} km/h, from historical averages.</li>
            <li><b>Linear regression</b>: one coefficient per variable, easy to explain.</li>
            <li><b>Decision tree</b>: readable rules (depth 10).</li>
            <li><b>Random Forest</b>: the average of many trees, robust.</li>
            <li><b>Gradient Boosting</b>: successive trees that correct errors, fast on large volumes.</li></ul></div>
      </div>
      <div class="panneau bloc"><h3>Performance on the test set</h3>
        <div class="table-zone"><table><thead><tr><th>Model</th><th class="num">MAE (min)</th><th class="num">Mean bias (min)</th><th class="num">RMSE (min)</th><th class="num">R²</th><th class="num">Training (s)</th></tr></thead><tbody>
          ${ml.modeles.map((m) => `<tr class="${m.modele === ml.modele_final ? "retenu" : ""}"><td>${m.modele}${m.modele === ml.modele_final ? " (selected)" : ""}</td><td class="num">${fmt(m.MAE, 2)}</td><td class="num">${fmt(m.Biais, 2)}</td><td class="num">${fmt(m.RMSE, 2)}</td><td class="num">${fmt(m.R2, 3)}</td><td class="num">${fmt(m.temps_entrainement_s, 1)}</td></tr>`).join("")}
        </tbody></table></div>
        <div class="grille g3" style="margin-top:14px">
          <div><h3>MAE</h3><p class="sous">mean error, smaller = better</p><div class="graph bas"><canvas id="g-mae"></canvas></div></div>
          <div><h3>RMSE</h3><p class="sous">penalises large errors</p><div class="graph bas"><canvas id="g-rmse"></canvas></div></div>
          <div><h3>Mean bias</h3><p class="sous">close to 0 = right on average</p><div class="graph bas"><canvas id="g-biais"></canvas></div></div>
        </div>
        <p class="lecture"><b>The baseline has the smallest MAE</b> (${fmt(BASE.MAE, 2)} min) because it predicts the "typical" trip. But it <b>underestimates each trip by ${fmt(Math.abs(BASE.Biais), 1)} min on average</b>, which is about ${fmt(Math.abs(BASE.Biais) * 20, 0)} min of error over a 20-trip route. ${ml.modele_final} has the best RMSE (${fmt(FIN.RMSE, 2)}), the best R² (${fmt(FIN.R2, 2)}) and an almost zero bias: it is the one we keep, because a route <b>adds up</b> the times.</p>
      </div>
      <div class="grille g2 bloc">
        <div class="panneau"><h3>Where does the model go wrong?</h3><p class="sous">Mean error by distance range</p><div class="graph"><canvas id="g-errdist"></canvas></div>
          <p class="lecture">On short trips, the formula does just as well. Beyond 5 km, its error explodes (more than 100 min beyond 15 km), whereas ML stays stable. ML is mainly useful to <b>avoid large errors</b>.</p></div>
        <div class="panneau"><h3>Which variables matter?</h3><p class="sous">Increase in MAE when the variable is randomly shuffled (min)</p><div class="graph"><canvas id="g-imp"></canvas></div>
          <p class="lecture"><b>Location</b> and <b>hour</b> weigh more than distance: some neighbourhoods and the afternoon are slower. R² remains modest (≈ ${fmt(FIN.R2, 2)}): part of the time depends on elements absent from the data.</p></div>
      </div>`;
    const bars = (id, field) => chart(id, { type: "bar", data: { labels: names.map((n) => n.replace(" (historical averages)", "")), datasets: [{ label: field, data: ml.modeles.map((m) => m[field]), backgroundColor: modelColors, borderRadius: 3 }] },
      options: { indexAxis: "y", plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => fmt(c.raw, 2) + " min" } } }, scales: { x: axis(""), y: { grid: { display: false }, ticks: { font: { size: 11 } } } } } });
    bars("g-mae", "MAE"); bars("g-rmse", "RMSE"); bars("g-biais", "Biais");
    const ED = ml.erreurs_par_distance;
    chart("g-errdist", { type: "bar", data: { labels: ED.bandes, datasets: [{ label: "Baseline (formula)", data: ED.baseline, backgroundColor: C.sans, borderRadius: 3 }, { label: ml.modele_final, data: ED.ml, backgroundColor: C.avec, borderRadius: 3 }] },
      options: { plugins: { tooltip: { callbacks: { label: (c) => c.dataset.label + ": " + fmt(c.raw, 1) + " min" } } }, scales: { y: axis("MAE (min)", { beginAtZero: true }), x: { grid: { display: false }, ticks: { font: { size: 10 } } } } } });
    const imp = Object.entries(ml.importances);
    chart("g-imp", { type: "bar", data: { labels: imp.map((i) => i[0]), datasets: [{ label: "Importance", data: imp.map((i) => i[1]), backgroundColor: C.avec, borderRadius: 3 }] },
      options: { indexAxis: "y", plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => "+" + fmt(c.raw, 2) + " min of MAE" } } }, scales: { x: axis("min"), y: { grid: { display: false } } } } });
  }

  // ======================= 6. SIMULATOR =======================
  function renderSimulator(el) {
    const scs = SC.scenarios;
    const demo = demoScenario();
    el.innerHTML = `
      <div class="entete"><h2 id="t-simulator">Route simulator</h2>
        <p>Choose a real test day and a policy. The browser <b>replays the day stop by stop</b>: at each stop, the optimiser recomputes the order of the visits already known. The time matrices (ML predictions, no-ML formula, evaluator) are precomputed by the Notebook; <b>the optimisation itself runs here</b>, with the same algorithm as in the Notebook.</p></div>
      <div class="sim">
        <form class="panneau commandes" id="f-sim">
          <label class="champ">Test day<select id="s-jour">${scs.map((s) => `<option value="${s.id}" ${s.id === demo.id ? "selected" : ""}>${dayName(s)}</option>`).join("")}</select></label>
          <label class="champ">Cost of one minute of lateness (λ)
            <span class="valeur-lambda" id="s-lval">${fmt(SC.lambda_defaut, 1)}</span>
            <input type="range" id="s-lambda" min="0" max="20" step="0.5" value="${SC.lambda_defaut}" aria-describedby="aide-l"></label>
          <p class="aide" id="aide-l">λ = 0: we only try to shorten the route. High λ: we accept detours to meet deadlines. Notebook value: ${fmt(SC.lambda_defaut, 0)}.</p>
          <fieldset><legend>Knowledge of the tasks</legend>
            <label class="radio"><input type="radio" name="s-info" value="reelle" checked><span>As in reality<small>a task is only planned after it has been accepted</small></span></label>
            <label class="radio"><input type="radio" name="s-info" value="totale"><span>All known from the start<small>optimistic scenario, to measure the cost of uncertainty</small></span></label>
          </fieldset>
          <button type="submit" class="principal">Simulate the day</button>
          <p class="aide">The three strategies start from the same first visit, at the same time. The time that actually elapses is given by the independent evaluator; the distance is exact.</p>
        </form>
        <div id="s-res"><div class="res-vide">Set the parameters then click “Simulate the day”.</div></div>
      </div>`;
    const lam = $("#s-lambda");
    lam.addEventListener("input", () => ($("#s-lval").textContent = fmt(+lam.value, 1)));
    $("#f-sim").addEventListener("submit", (e) => { e.preventDefault(); run(); });
    run();

    function run() {
      const sc = scs.find((s) => s.id === +$("#s-jour").value);
      const l = +lam.value, allKnown = el.querySelector('input[name="s-info"]:checked').value === "totale";
      const t0 = performance.now();
      const res = { reel: SIM.simuler(sc, "reel", l), sans_ml: SIM.simuler(sc, "sans_ml", l, allKnown), avec_ml: SIM.simuler(sc, "avec_ml", l, allKnown) };
      const elapsed = performance.now() - t0;
      // Consistency check with the Notebook (same parameters as the Notebook)
      let parity = "";
      if (l === SC.lambda_defaut && !allKnown) {
        const ok = ["reel", "sans_ml", "avec_ml"].every((s) => ["distance_km", "deplacement_min", "n_retard", "retard_min"].every((c) => Math.abs(res[s][c] - sc.resultats_notebook[s][c]) < 1e-6));
        parity = ok ? `<p class="parite">Results identical to those computed by the Notebook for this day (λ = ${fmt(l, 0)}).</p>`
                    : `<p class="parite diff">Difference with the Notebook detected for this day: check that data_en/donnees.js was regenerated by the latest Notebook run.</p>`;
      }
      const base = res.reel;
      const line = (s, label, field, d, unit) => {
        const v = res[s][field], r = base[field];
        let gap = "";
        if (s !== "reel" && r > 0) { const p = change(r, v); gap = `<span class="ecart ${p < -0.05 ? "mieux" : p > 0.05 ? "pire" : ""}">${signed(p, 0)}</span>`; }
        else if (s !== "reel" && field === "n_retard" && v > r) gap = `<span class="ecart pire">+${v - r}</span>`;
        return `<dt>${label}</dt><dd>${field === "n_retard" ? v : fmt(v, d)} ${unit}${gap}</dd>`;
      };
      const stratCard = (s) => `<div class="strat" style="--c:${COLOR[s]}"><h3>${NAMES[s]}</h3><dl>
        ${line(s, "Distance", "distance_km", 2, "km")}${line(s, "Travel time", "deplacement_min", 0, "min")}${line(s, "Total duration", "duree_min", 0, "min")}
        ${line(s, "Late pickups", "n_retard", 0, "")}${line(s, "Minutes late", "retard_min", 0, "min")}</dl></div>`;
      const m = res.avec_ml, sa = res.sans_ml;
      const advice = (() => {
        const dKm = change(base.distance_km, m.distance_km), dT = change(base.deplacement_min, m.deplacement_min);
        let t = `With ML, the route changes by ${signed(dKm, 0)} in distance and ${signed(dT, 0)} in travel time compared with the real order. `;
        if (m.n_retard < sa.n_retard) t += `It has <b>${sa.n_retard - m.n_retard} fewer late pickup(s)</b> than optimisation without ML, which underestimates times. `;
        else if (m.n_retard > sa.n_retard) t += `Here, it has ${m.n_retard - sa.n_retard} more late pickup(s) than optimisation without ML: ML is not better on every day. `;
        else t += `Both optimisers have the same number of late pickups on this day. `;
        if (l === 0) t += "With λ = 0, lateness is not penalised: the optimiser only looks for the shortest path.";
        else t += "<b>Recommended decision:</b> follow the “with ML” order, which keeps most of the distance gain while protecting deadlines.";
        return t;
      })();
      $("#s-res").innerHTML = `
        <div class="trois">${stratCard("reel")}${stratCard("sans_ml")}${stratCard("avec_ml")}</div>
        <div class="panneau bloc verdict" style="margin-top:14px"><h3>What this day shows</h3><p>${advice}</p>
          ${allKnown ? "<p class='aide'>Optimistic scenario: the real order is still replayed as is, with its known-task constraint.</p>" : ""}
          ${parity}<p class="aide">${sc.n} visits, ${res.avec_ml.journal.length + res.sans_ml.journal.length} optimised decisions in ${fmt(elapsed, 0)} ms in your browser.</p></div>
        <div class="grille g2 bloc">
          <div class="panneau"><h3>KPI comparison</h3><p class="sous">Values for the simulated day</p>
            <div class="grille g3" style="gap:8px">
              <div><div class="graph haut"><canvas id="gs-km"></canvas></div></div>
              <div><div class="graph haut"><canvas id="gs-min"></canvas></div></div>
              <div><div class="graph haut"><canvas id="gs-ret"></canvas></div></div></div>
            <p class="lecture">The percentages on the cards above are computed against the courier's real order, replayed under the same conditions.</p></div>
          <div class="panneau carte-sim"><h3>Route map</h3>
            <div class="bascule" role="group" aria-label="Route displayed"><button type="button" data-s="avec_ml" aria-pressed="true">With ML</button><button type="button" data-s="sans_ml" aria-pressed="false">No ML</button><button type="button" data-s="reel" aria-pressed="false">Real</button></div>
            <p class="sous" style="margin-top:6px">Solid line: chosen route, numbered in visiting order. Grey dashes: real order. Dark orange circle: late pickup.</p>
            <canvas id="s-carte"></canvas></div>
        </div>
        <div class="panneau bloc"><h3>Decision log with ML</h3><p class="sous">At each stop: how many tasks were known, and where the optimiser sent the courier</p>
          <div class="table-zone" style="max-height:360px;overflow-y:auto"><table class="journal"><thead><tr><th>Stop</th><th>Departure</th><th>From</th><th>To</th><th class="num">Known tasks</th><th class="num">Distance</th><th class="num">Time</th><th>Arrival</th></tr></thead><tbody>
          ${m.journal.map((j, k) => `<tr><td>${k + 1}</td><td>${clock(j.depart)}</td><td>visit ${j.de + 1}</td><td>visit ${j.vers + 1}</td><td class="num">${j.connues}</td><td class="num">${fmt(j.km, 2)} km</td><td class="num">${fmt(j.duree, 1)} min</td><td class="${j.retard ? "retard" : ""}">${clock(j.arrivee)}${j.retard ? " (late)" : ""}</td></tr>`).join("")}
          </tbody></table></div></div>`;
      const mini = (id, title, field, d) => chart(id, { type: "bar", data: { labels: ["Real", "No ML", "With ML"], datasets: [{ label: title, data: ["reel", "sans_ml", "avec_ml"].map((s) => res[s][field]), backgroundColor: [C.reel, C.sans, C.avec], borderRadius: 3 }] },
        options: { plugins: { legend: { display: false }, title: { display: true, text: title, color: "#102a43", font: { weight: 600 } }, tooltip: { callbacks: { label: (c) => fmt(c.raw, d) } } }, scales: { y: axis("", { beginAtZero: true }), x: { grid: { display: false }, ticks: { font: { size: 10 } } } } } });
      mini("gs-km", "Distance (km)", "distance_km", 2); mini("gs-min", "Travel time (min)", "deplacement_min", 0); mini("gs-ret", "Late pickups", "n_retard", 0);
      const paint = (s) => {
        const late = new Set(res[s].journal.filter((j) => j.retard).map((j) => j.vers));
        const routes = s === "reel" ? [{ ordre: res.reel.ordre, couleur: C.reel, epaisseur: 2.6 }]
          : [{ ordre: res.reel.ordre, couleur: C.reel, epaisseur: 1.6, alpha: 0.6, pointille: true }, { ordre: res[s].ordre, couleur: COLOR[s], epaisseur: 2.6 }];
        drawMap($("#s-carte"), sc, routes, { retards: late });
      };
      $("#s-res").querySelectorAll(".bascule button").forEach((b) => b.addEventListener("click", () => {
        $("#s-res").querySelectorAll(".bascule button").forEach((x) => x.setAttribute("aria-pressed", String(x === b))); paint(b.dataset.s); }));
      requestAnimationFrame(() => paint("avec_ml"));
    }
  }

  // ======================= 7. BEFORE / AFTER =======================
  function renderComparison(el) {
    const G = op.gains, mv = op.milp_vs_heuristique, sens = op.sensibilite_lambda;
    const row = (label, v, ref, d, unit) => { const p = change(ref, v); return `<div class="ligne"><span>${label}<span class="ref">real: ${fmt(ref, d)} ${unit}</span></span><span><b>${fmt(v, d)}</b> ${unit} <span class="ecart ${p < 0 ? "mieux" : "pire"}">${signed(p, 0)}</span></span></div>`; };
    el.innerHTML = `
      <div class="entete"><h2 id="t-comparison">Before / after: the proof over ${op.n_journees} days</h2>
        <p>Averages per test day (September–October), λ = ${fmt(op.lambda, 0)}. Both scenarios use the <b>same optimiser</b>; only the time matrix changes. Percentages are computed against the real order of the couriers.</p></div>
      <div class="duel">
        <div style="--c:${C.sans}"><h3>Without Machine Learning</h3><p class="sous">Formula: ${fmt(ml.baseline.service_median_min, 0)} min + distance ÷ ${fmt(ml.baseline.vitesse_mediane_kmh, 1)} km/h</p>
          ${row("Distance travelled", KS.distance_km, KR.distance_km, 2, "km")}${row("Travel time", KS.deplacement_min, KR.deplacement_min, 1, "min")}${row("Route duration", KS.duree_min, KR.duree_min, 1, "min")}${row("Late pickups", KS.n_retard, KR.n_retard, 2, "")}${row("Minutes late", KS.retard_min, KR.retard_min, 1, "min")}</div>
        <div style="--c:${C.avec}"><h3>With Machine Learning</h3><p class="sous">Hourly matrix predicted by ${ml.modele_final}</p>
          ${row("Distance travelled", KM.distance_km, KR.distance_km, 2, "km")}${row("Travel time", KM.deplacement_min, KR.deplacement_min, 1, "min")}${row("Route duration", KM.duree_min, KR.duree_min, 1, "min")}${row("Late pickups", KM.n_retard, KR.n_retard, 2, "")}${row("Minutes late", KM.retard_min, KR.retard_min, 1, "min")}</div>
      </div>
      <div class="grille g3 bloc">
        <div class="encadre"><h3>Value of optimisation</h3><p>Compared with real couriers, optimisation with ML reduces distance by <b>${fmt(-G.distance_avec_vs_reel_pct, 1)}%</b> and travel time by <b>${fmt(-G.deplacement_avec_vs_reel_pct, 1)}%</b>. It does better than reality on ${pct(G.part_journees_ml_meilleur_que_reel_deplacement)} of the days (Wilcoxon, p &lt; 0.001).</p></div>
        <div class="encadre"><h3>Value of ML</h3><p>Compared with optimisation without ML, lateness drops by <b>${fmt(-change(KS.n_retard, KM.n_retard), 0)}%</b>. In return, distance increases by ${fmt(G.distance_avec_vs_sans_pct, 1)}% and travel time by ${fmt(G.deplacement_avec_vs_sans_pct, 1)}%.</p></div>
        <div class="encadre orange"><h3>The trade-off, honestly</h3><p>Without ML, the optimiser saves more kilometres but causes <b>more lateness than the field</b>, because its formula underestimates times by ${fmt(Math.abs(BASE.Biais), 1)} min per trip. ML does not shorten routes further: it makes the plan <b>reliable</b>.</p></div>
      </div>
      <div class="grille g2 bloc">
        <div class="panneau"><h3>Time gain per day</h3><p class="sous">Number of days by travel-time gain compared with reality</p><div class="graph"><canvas id="g-gains"></canvas></div>
          <p class="lecture">Median gain: ${fmt(op.gain_median_deplacement_pct.sans_ml, 1)}% without ML, ${fmt(op.gain_median_deplacement_pct.avec_ml, 1)}% with ML. A few days are worse than reality: the courier sometimes knows things absent from the data.</p></div>
        <div class="panneau"><h3>The time / lateness trade-off by λ</h3><p class="sous">50 days; each point is a value of λ (0, 1, 5, 20)</p><div class="graph"><canvas id="g-sens"></canvas></div>
          <p class="lecture">Even with a heavy penalty, the optimiser without ML plateaus on lateness: <b>a good penalty does not compensate for a bad prediction</b>.</p></div>
      </div>
      <div class="grille g3 bloc">
        <div class="chiffre"><div class="val">${fmt(mv.ecart_moyen_pct, 2)}<small>%</small></div><div class="lib">mean gap of the heuristic to the exact optimum (HiGHS MILP, ${mv.n_instances} instances of 8 visits)</div></div>
        <div class="chiffre"><div class="val">${fmt(mv.temps_heuristique_moyen_s * 1000, 1)}<small> ms</small></div><div class="lib">per decision for the heuristic, versus ${fmt(mv.temps_milp_moyen_s, 2)} s for the exact MILP</div></div>
        <div class="chiffre"><div class="val">${fmt(op.validation_evaluateur.correlation, 2)}</div><div class="lib">correlation between simulated and real route durations (independent evaluator)</div></div>
      </div>
      <div class="encadre orange bloc"><h3>What is observed, what is simulated</h3><p><b>Observed:</b> the real order, positions, windows, distances. <b>Simulated:</b> the times of the optimised routes, which were never driven. The evaluator overestimates lateness in absolute terms (${fmt(KR.n_retard, 2)} simulated versus ${fmt(op.retards_observes_moyens, 2)} observed per day). Only <b>comparisons between strategies</b>, all scored the same way, can therefore be interpreted.</p></div>`;
    const gs = op.gains_par_journee_pct, all = gs.sans_ml.concat(gs.avec_ml);
    const lo = Math.floor(Math.min(...all) / 2.5) * 2.5, hi = Math.ceil(Math.max(...all) / 2.5) * 2.5, bins = [];
    for (let x = lo; x < hi; x += 2.5) bins.push(x);
    const count = (arr) => bins.map((b) => arr.filter((v) => v >= b && v < b + 2.5).length);
    chart("g-gains", { type: "bar", data: { labels: bins.map((b) => fmt(b, 1) + " to " + fmt(b + 2.5, 1)), datasets: [
      { label: NAMES.sans_ml, data: count(gs.sans_ml), backgroundColor: C.sans, borderRadius: 2 }, { label: NAMES.avec_ml, data: count(gs.avec_ml), backgroundColor: C.avec, borderRadius: 2 }] },
      options: { plugins: { tooltip: { callbacks: { title: (c) => "Gain of " + c[0].label + "%", label: (c) => c.dataset.label + ": " + c.raw + " days" } } }, scales: { y: axis("Days"), x: axis("Gain (%) — positive = better than real", { grid: { display: false }, ticks: { maxTicksLimit: 10, font: { size: 10 } } }) } } });
    const series = (s) => sens.filter((r) => r.strategie === s).map((r) => ({ x: r.deplacement_min, y: r.n_retard, l: r.lambda }));
    chart("g-sens", { type: "scatter", data: { datasets: [
      { label: NAMES.sans_ml, data: series("sans_ml"), borderColor: C.sans, backgroundColor: C.sans, showLine: true, pointRadius: 5 },
      { label: NAMES.avec_ml, data: series("avec_ml"), borderColor: C.avec, backgroundColor: C.avec, showLine: true, pointRadius: 5 },
      { label: NAMES.reel, data: [{ x: op.reel_50.deplacement_min, y: op.reel_50.n_retard, l: null }], backgroundColor: C.reel, pointRadius: 7 }] },
      options: { plugins: { tooltip: { callbacks: { label: (c) => c.dataset.label + (c.raw.l !== null ? " (λ = " + fmt(c.raw.l, 0) + ")" : "") + ": " + fmt(c.raw.x, 0) + " min, " + fmt(c.raw.y, 2) + " late" } } },
        scales: { x: axis("Mean travel time (min / day)"), y: axis("Mean late pickups / day", { beginAtZero: true }) } } });
  }

  // ======================= 8. CONCLUSION =======================
  function renderConclusion(el) {
    const b = op.borne_information_parfaite;
    el.innerHTML = `
      <div class="entete"><h2 id="t-conclusion">Conclusion</h2><p>What the project shows, and what it does not.</p></div>
      <div class="grille g2">
        <div class="panneau"><h3>Main results</h3><ul class="liste-simple">
          <li>Real couriers already meet deadlines (${pct(ind.taux_retard_reel, 2)} lateness), but only ${pct(ind.part_connue_avant_debut)} of the tasks are known in the morning: the optimisation has to be <b>dynamic</b>.</li>
          <li>${ml.modele_final} predicts <b>unbiased</b> times (${fmt(FIN.Biais, 2)} min), whereas the historical average underestimates them by ${fmt(Math.abs(BASE.Biais), 1)} min per trip.</li>
          <li>Optimisation with ML reduces distance by ${fmt(-op.gains.distance_avec_vs_reel_pct, 1)}% and travel time by ${fmt(-op.gains.deplacement_avec_vs_reel_pct, 1)}% compared with the field (simulation).</li>
          <li>Compared with optimisation without ML, ML reduces lateness by ${fmt(-change(KS.n_retard, KM.n_retard), 0)}%, at the price of ${fmt(op.gains.distance_avec_vs_sans_pct, 1)}% more distance.</li>
          <li>If all tasks were known in the morning, travel time would fall to ${fmt(b.deplacement_min, 0)} min per day over 50 days: this is the cost of uncertainty.</li></ul></div>
        <div class="panneau"><h3>The added value of ML</h3>
          <p>ML does not work "magic" on kilometres. It gives the optimiser times that are <b>right on average</b> and depend on the neighbourhood and the hour. The result: a plan that keeps its promises, with less lateness, without losing the gain from optimisation.</p>
          <h3 style="margin-top:12px">Limitations</h3><ul class="liste-simple">
            <li>Time gains are simulated: a route that was never driven cannot be observed.</li>
            <li>The model's R² remains modest (${fmt(FIN.R2, 2)}); the evaluator overestimates lateness in absolute terms.</li>
            <li>Distances are straight-line, and the real courier faces constraints absent from the data.</li></ul>
          <h3 style="margin-top:12px">Improvement ideas</h3><ul class="liste-simple">
            <li>Road distances from the network provided by LaDe (roads.csv).</li>
            <li>Several couriers at once (VRPTW) to reassign visits.</li>
            <li>Forecast the arrival of upcoming requests to anticipate detours.</li></ul></div>
      </div>
      <div class="panneau bloc"><h3>Project documents</h3><p>The Notebook is the source of truth: the report and this platform use its figures and exports.</p>
        <div class="liens"><a href="../rapport/rapport_final_en.pdf">Open the report (PDF)</a><a class="second" href="../rapport/rapport_final_en.docx">Editable report (DOCX)</a><a class="second" href="../notebook/projet_tournees_lade_en.ipynb">Download the Notebook</a></div></div>`;
  }

  show(location.hash.slice(1) || "home");
})();
